pm.test('Status code is 200', () => {
  pm.response.to.have.status(200);
});

pm.test('Response contains paginated equipment list', () => {
  const body = pm.response.json();

  pm.expect(body).to.have.property('data');
  pm.expect(body.data).to.be.an('array');

  pm.expect(body).to.have.property('meta');
  pm.expect(body.meta).to.have.property('total');
  pm.expect(body.meta).to.have.property('page');
  pm.expect(body.meta).to.have.property('limit');
});

pm.test('Created equipment is present in the list', () => {
  const body = pm.response.json();
  const equipmentId = pm.collectionVariables.get('equipmentId');

  const equipment = body.data.find((item) => item.id === equipmentId);

  pm.expect(equipment).to.exist;
});

