pm.test('Status code is 200', () => {
  pm.response.to.have.status(200);
});

pm.test('Weather data is returned for correct equipment', () => {
  const body = pm.response.json();

  pm.expect(body).to.have.property('data');
  pm.expect(body.data.equipmentId).to.eql(
    pm.collectionVariables.get('equipmentId'),
  );
  pm.expect(body.data).to.have.property('location');
  pm.expect(body.data).to.have.property('timezone');
  pm.expect(body.data.days).to.be.an('array');
  pm.expect(body.data.days.length).to.be.above(0);
});

pm.test('Forecast contains required fields', () => {
  const day = pm.response.json().data.days[0];

  pm.expect(day).to.have.property('date');
  pm.expect(day).to.have.property('temperatureMax');
  pm.expect(day).to.have.property('temperatureMin');
  pm.expect(day).to.have.property('precipitation');
  pm.expect(day).to.have.property('windSpeedMax');
  pm.expect(day).to.have.property('suitableForOutdoorWork');
  pm.expect(day.suitableForOutdoorWork).to.be.a('boolean');
});

