pm.test("Status is 200", () => {
  pm.response.to.have.status(200);
});

if (pm.response.code === 200) {
  const data = pm.response.json().data;
  const cookie = pm.response.headers.get("Set-Cookie") || "";
  const match = cookie.match(/(?:^|;\s*)refresh_token=([^;]+)/);

  pm.test("Refresh cookie has required attributes", () => {
    pm.expect(match).not.to.eql(null);
    pm.expect(cookie).to.include("HttpOnly");
    pm.expect(cookie).to.include("Secure");
    pm.expect(cookie).to.include("SameSite=Lax");
    pm.expect(cookie).to.include("Path=/api/auth");
  });

  pm.test("JSON contains no refresh token or password hash", () => {
    pm.expect(data).not.to.have.property("refreshToken");
    pm.expect(data.user).not.to.have.property("passwordHash");
  });

  if (match) {
    pm.collectionVariables.set("authAccessToken", data.accessToken);
    pm.collectionVariables.set("authRefreshToken", match[1]);
    pm.collectionVariables.unset("authOldRefreshToken");
  }
}

